    assertEq(created.x(), 15, "10 + 5 deve fare 15");
    created.incrementByArg(0);
    assertEq(created.get(), 15, "incrementare di 0 non cambia x");
  }

  function test_OverflowReverts() public {
    // x = 10: aggiungere type(uint256).max - 9 supera il massimo
    vm.expectRevert(stdError.arithmeticError); // panic 0x11
    created.incrementByArg(type(uint256).max - 9);
  }

  function test_MaxWithoutOverflow() public {
    created.incrementByArg(type(uint256).max - 10);
    assertEq(created.x(), type(uint256).max);
  }
}

