// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {Creator, Created} from "../Creator.sol";
import {CreatorFixed} from "./CreatorFixed.sol";
import {Test} from "forge-std/Test.sol";

contract Ex4Test is Test {
  address alice = makeAddr("alice");

  function test_OriginalLocksLeftover() public {
    Creator c = new Creator();
    vm.deal(alice, 1 ether);
    vm.prank(alice);
    c.createAndEndowCreated{value: 1000}(5, 100);
    // 900 wei restano nel Creator, che non ha modo di restituirli
    assertEq(address(c).balance, 900);
  }

  function test_OriginalAnyoneCanOverride() public {
    Creator c = new Creator();
    c.createCreated(1);
    Created evil = new Created(999);
    vm.prank(alice);
    c.overrideCreated(address(evil));        // nessun controllo: passa
    assertEq(c.getInnerContractX(), 999);
  }

  function test_FixedOverrideOnlyOwner() public {
    CreatorFixed c = new CreatorFixed();
    vm.prank(alice);
    vm.expectRevert(bytes("not owner"));
    c.overrideCreated(address(0xBEEF));
  }

  function test_FixedEndowAll() public {
    CreatorFixed c = new CreatorFixed();
    Created inner = c.createAndEndowCreated{value: 1000}(5);
    assertEq(address(c).balance, 0);
    assertEq(address(inner).balance, 1000);
    assertEq(address(c.innerContract()), address(inner));
  }
}

