pragma solidity ^0.8.28;

import {Creator, Created, CreatedWithEvent} from "./Creator.sol";
import {Test} from "forge-std/Test.sol";
import "hardhat/console.sol";

contract CreatorTest is Test {
  Creator creator;

  function setUp() public {
    creator = new Creator();
  }

  // senza createCreated l'indirizzo interno è 0x0: chiamare x() su un indirizzo
  // senza codice fa revert (Solidity controlla extcodesize prima della chiamata)
  function test_NoInnerContractReverts() public {
    assertEq(creator.getInnerContractAddr(), address(0));
    vm.expectRevert();
    creator.getInnerContractX();
  }

  function test_CreateAndIncrement() public {
    creator.createCreated(7);
    address inner = creator.getInnerContractAddr();
    console.log("Created deployed at %s", inner);
    assertEq(creator.getInnerContractX(), 7);
    creator.incrementInnerContractX();
    assertEq(creator.getInnerContractX(), 8);
    // lo stesso valore letto direttamente dal contratto figlio
    assertEq(Created(inner).get(), 8);
  }

  function test_OverrideCreated() public {
    Created other = new Created(100);
    creator.overrideCreated(address(other));
    assertEq(creator.getInnerContractAddr(), address(other));
    creator.incrementInnerContractX();
    assertEq(other.x(), 101);
  }

  function test_CreateAndEndow() public {
    vm.deal(address(this), 1 ether);   // cheatcode: dà 1 ether al contratto di test
    creator.createAndEndowCreated{value: 1000}(5, 300);
    // il figlio ha ricevuto 300 wei, gli altri 700 restano nel Creator
    assertEq(address(creator).balance, 700);
  }

  // valore troppo alto: il Creator non ha abbastanza ether, la creazione fallisce
  function test_CreateAndEndowTooMuchReverts() public {
    vm.expectRevert();
    creator.createAndEndowCreated{value: 10}(5, 300);
  }

